# Load all demo pairs for this task session
import os, glob, re, json

d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
if not d:
    print("RLM_SESSION_DIR not set")
else:
    print(f"Session dir: {d}")
    # Load the session log
    log_path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    try:
        text = open(log_path).read()
        print(f"Loaded log with {len(text)} chars")

        # Find demo pairs
        demos = {}
        pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
        for match in re.finditer(pattern, text):
            name, h, w = match.groups()
            h = int(h)
            w = int(w)
            rest = text[match.end():]
            rows = [s.strip() for s in rest.split('\n')[:h]]
            if all(len(r) == w for r in rows):
                # Parse the next h lines of grid data
                grids = []
                for row in rows[:h]:
                    grids.append([int(x) for x in row.split()])
                # Store by key
                key = name.split()[0]  # e.g., "Demo pair 1"
                demos[key] = {
                    'grid': grids,
                    'dimensions': (h, w),
                    'type': 'input' if 'input' in name else 'output' if 'input' not in name else None
                }

        for k, v in demos.items():
            print(f"{k}: {v['dimensions']} - {v.get('type', 'unknown')}")
            if v['type'] == 'input':
                print(f"  First row: {v['grid'][0][:20]}...")

    except Exception as e:
        print(f"Error: {e}")

