with open(log_path) as f:
    msgs = [json.loads(line) for line in f.readlines()]

# Look for ARC-style grid data (arrays of numbers)
for msg in msgs:
    if msg.get('type') == 'message':
        content = msg.get('content', [])
        if isinstance(content, list):
            for item in content:
                if item.get('type') == 'text':
                    text = item.get('text', '')
                    # Look for array patterns
                    if '[' in text and ']' in text:
                        # Might be JSON or code with grid
                        m = re.search(r'(\[[\d\s,\[\]]+\])+', text)
                        if m:
                            print(f"Found array: {m.group()[:200]}")
                            break

