print("\n\nSearching for [number] patterns in message content:")
for msg in msgs:
    text = str(msg).lower()
    if '[' in text and str(msg).upper().count("'[") > 0:
        # Check if it's a grid
        if re.search(r'\[\d+\]\s*\d+', text):
            print(f"Found [number] pattern in message: {msg.get('id')[:16]}")

